/**
 * Made-up sample data for the "building a cladogram" animation (A3.2.6). The four sequences were
 * generated by placing ten single-base substitutions on the tree (((P,Q),R),S), so the most
 * parsimonious tree needs 10 changes. Unit tests check every number the animation shows.
 */
export const species = ['P', 'Q', 'R', 'S'] as const;
export type Sp = (typeof species)[number];

export const sequences: Record<Sp, string> = {
  P: 'ACGCTATTGAAGCACA',
  Q: 'ACGCTAGTGAAGCACG',
  R: 'ATGCTATCGACGCACG',
  S: 'ATACCATTGGCGTATG',
};

/** Positions (0-based) where not all sequences have the same base. */
export function variableSites(seqs: string[] = Object.values(sequences)): number[] {
  const n = seqs[0]!.length;
  return Array.from({ length: n }, (_, i) => i).filter((i) => new Set(seqs.map((s) => s[i])).size > 1);
}

export function differences(a: string, b: string): number {
  let d = 0;
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) d++;
  return d;
}

export const pairs: [Sp, Sp][] = [['P', 'Q'], ['P', 'R'], ['Q', 'R'], ['P', 'S'], ['Q', 'S'], ['R', 'S']];

/** A rooted binary tree written as nested pairs of species names. */
export type T = Sp | [T, T];

/** Minimum number of base changes needed on a tree (Fitch parsimony, one site at a time). */
export function parsimonyScore(tree: T, seqs: Record<Sp, string> = sequences): number {
  const len = seqs.P.length;
  let total = 0;
  for (let i = 0; i < len; i++) {
    const walk = (t: T): Set<string> => {
      if (typeof t === 'string') return new Set([seqs[t][i]!]);
      const a = walk(t[0]), b = walk(t[1]);
      const both = new Set([...a].filter((x) => b.has(x)));
      if (both.size) return both;
      total++;
      return new Set([...a, ...b]);
    };
    walk(tree);
  }
  return total;
}

export const bestTree: T = [[['P', 'Q'], 'R'], 'S'];
export const altTree: T = [[['P', 'R'], 'Q'], 'S'];
